from __future__ import annotations
import cmath
import math


def zeros(lam: float, q: float) -> tuple[complex, complex]:
    d = cmath.sqrt(complex(lam*lam - 4*q))
    return (lam+d)/(2*q), (lam-d)/(2*q)


def svg(lam: float = 2.0, q: float = 2.0) -> str:
    zs=zeros(lam,q); r=1/math.sqrt(q); scale=160; cx=cy=200
    points="".join(f'<circle cx="{cx+scale*z.real:.2f}" cy="{cy-scale*z.imag:.2f}" r="7" fill="#e63946"/>' for z in zs)
    return f'<svg xmlns="http://www.w3.org/2000/svg" width="400" height="400"><rect width="100%" height="100%" fill="#fbfbff"/><circle cx="200" cy="200" r="{scale*r}" fill="none" stroke="#3157a4" stroke-width="3"/><line x1="20" y1="200" x2="380" y2="200" stroke="#999"/><line x1="200" y1="20" x2="200" y2="380" stroke="#999"/>{points}</svg>'

if __name__ == "__main__":
    open("critical_circle.svg","w",encoding="utf-8").write(svg())

from __future__ import annotations
import csv


def coefficients(lam: float, q: float, count: int) -> list[float]:
    out=[2.0,lam]
    while len(out)<count: out.append(lam*out[-1]-q*out[-2])
    return out[:count]

if __name__ == "__main__":
    with open("power_sums.csv","w",newline="",encoding="utf-8") as f:
        writer=csv.writer(f); writer.writerow(["n","S_n","normalized_S_n"]); q=2.0
        for n,value in enumerate(coefficients(2.0,q,40)):
            writer.writerow([n,value,value/(q**(n/2))])

from __future__ import annotations
import csv


def residual_size(lam: complex, q: complex, n: int, u: complex) -> float:
    s=[2+0j,lam]
    while len(s)<n+3: s.append(lam*s[-1]-q*s[-2])
    t=sum(s[k+1]*u**k for k in range(n+1))
    lhs=(1-lam*u+q*u*u)*t
    rhs=lam-2*q*u-s[n+2]*u**(n+1)+q*s[n+1]*u**(n+2)
    return abs(lhs-rhs)

if __name__ == "__main__":
    with open("residuals.csv","w",newline="",encoding="utf-8") as f:
        w=csv.writer(f); w.writerow(["N","absolute_residual"]); u=0.1+0.2j
        for n in range(31): w.writerow([n,residual_size(2,2,n,u)])

